public record GenerateReportRequest(Guid CustomerId, DateTime From, DateTime To);

app.MapPost("/reports", async (GenerateReportRequest req, IBackgroundJobQueue queue) => {
    var jobId = Guid.NewGuid();
    await queue.EnqueueAsync(new GenerateReportJob(jobId, req));
    return Results.Accepted($"/reports/{jobId}", new { jobId, status = "queued" });
})
.WithName("GenerateReport");

app.MapGet("/reports/{jobId:guid}", async (Guid jobId, AppDb db) => {
    var job = await db.ReportJobs.FindAsync(jobId);
    return job is null ? Results.NotFound() : Results.Json(job);
});
